import hmac
import hashlib
import time
import os
import re
import unicodedata
from flask import Flask, request, jsonify, abort
from functools import wraps
import sqlite3
import secrets

app = Flask(__name__)

SECRET_KEY = os.environ.get('HMAC_SECRET', secrets.token_hex(32))
DB_PATH = os.environ.get('DB_PATH', '/tmp/secure_notes.db')
TOKEN_EXPIRY = 3600  # 1 hour

def get_db():
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    return conn

def init_db():
    conn = get_db()
    conn.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        api_key_hash TEXT NOT NULL,
        role TEXT DEFAULT 'user'
    )''')
    conn.execute('''CREATE TABLE IF NOT EXISTS notes (
        id INTEGER PRIMARY KEY,
        user_id INTEGER NOT NULL,
        title TEXT NOT NULL,
        content TEXT NOT NULL,
        private INTEGER DEFAULT 1,
        FOREIGN KEY (user_id) REFERENCES users(id)
    )''')
    conn.commit()
    conn.close()

def compute_signature(message, key=SECRET_KEY):
    """Compute HMAC-SHA256 signature for API authentication."""
    return hmac.new(
        key.encode('utf-8'),
        message.encode('utf-8'),
        hashlib.sha256
    ).hexdigest()

def verify_signature(message, provided_sig, key=SECRET_KEY):
    """Verify HMAC signature using constant-time comparison."""
    expected = compute_signature(message, key)
    return hmac.compare_digest(expected, provided_sig)

def canonicalize_username(username):
    """Canonicalize username for consistent lookup.
    Applies NFKC normalization to handle equivalent Unicode forms."""
    # Strip whitespace and normalize
    cleaned = username.strip()
    # NFKC normalization for compatibility equivalence
    normalized = unicodedata.normalize('NFKC', cleaned)
    return normalized.lower()

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        auth_header = request.headers.get('Authorization', '')
        timestamp = request.headers.get('X-Timestamp', '')
        signature = request.headers.get('X-Signature', '')

        if not auth_header or not timestamp or not signature:
            abort(401, description='Missing authentication headers')

        # Check timestamp freshness (replay protection)
        try:
            ts = int(timestamp)
        except (ValueError, TypeError):
            abort(401, description='Invalid timestamp')

        current_time = int(time.time())
        if abs(current_time - ts) > TOKEN_EXPIRY:
            abort(401, description='Request expired')

        # Extract username from auth header
        if not auth_header.startswith('HMAC '):
            abort(401, description='Invalid auth scheme')

        username = auth_header[5:]  # Remove 'HMAC ' prefix

        # Build the message to verify
        # message = method + path + timestamp + body
        body = request.get_data(as_text=True) or ''
        sign_message = f"{request.method}:{request.path}:{timestamp}:{body}"

        # Look up user's API key
        canon_user = canonicalize_username(username)
        conn = get_db()
        user = conn.execute(
            'SELECT * FROM users WHERE username = ?',
            (canon_user,)
        ).fetchone()
        conn.close()

        if not user:
            abort(401, description='User not found')

        # Verify signature using user's stored key
        if not verify_signature(sign_message, signature, user['api_key_hash']):
            abort(401, description='Invalid signature')

        request.current_user = dict(user)
        return f(*args, **kwargs)
    return decorated

def require_admin(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        if request.current_user.get('role') != 'admin':
            abort(403, description='Admin access required')
        return f(*args, **kwargs)
    return decorated

@app.route('/api/notes', methods=['GET'])
@require_auth
def list_notes():
    user = request.current_user
    conn = get_db()
    if user['role'] == 'admin':
        notes = conn.execute('SELECT * FROM notes').fetchall()
    else:
        notes = conn.execute(
            'SELECT * FROM notes WHERE user_id = ? OR private = 0',
            (user['id'],)
        ).fetchall()
    conn.close()
    return jsonify([dict(n) for n in notes])

@app.route('/api/notes', methods=['POST'])
@require_auth
def create_note():
    data = request.get_json()
    if not data or 'title' not in data or 'content' not in data:
        abort(400, description='Missing title or content')

    title = str(data['title'])[:200]
    content = str(data['content'])[:10000]
    private = 1 if data.get('private', True) else 0

    conn = get_db()
    conn.execute(
        'INSERT INTO notes (user_id, title, content, private) VALUES (?, ?, ?, ?)',
        (request.current_user['id'], title, content, private)
    )
    conn.commit()
    conn.close()
    return jsonify({'status': 'created'}), 201

@app.route('/api/admin/users', methods=['GET'])
@require_auth
@require_admin
def list_users():
    conn = get_db()
    users = conn.execute('SELECT id, username, role FROM users').fetchall()
    conn.close()
    return jsonify([dict(u) for u in users])

@app.route('/api/register', methods=['POST'])
def register():
    data = request.get_json()
    if not data or 'username' not in data:
        abort(400, description='Missing username')

    raw_username = str(data['username'])

    # Validate username format before normalization
    if not re.match(r'^[\w.@+-]+$', raw_username, re.UNICODE):
        abort(400, description='Invalid username characters')

    if len(raw_username) > 64:
        abort(400, description='Username too long')

    # Generate API key for the user
    api_key = secrets.token_hex(32)

    # Store with canonicalized username
    canon_user = canonicalize_username(raw_username)

    conn = get_db()
    try:
        conn.execute(
            'INSERT INTO users (username, api_key_hash, role) VALUES (?, ?, ?)',
            (canon_user, api_key, 'user')
        )
        conn.commit()
    except sqlite3.IntegrityError:
        conn.close()
        abort(409, description='Username already exists')
    conn.close()

    return jsonify({
        'username': canon_user,
        'api_key': api_key,
        'message': 'Use api_key as HMAC key for signing requests'
    }), 201

init_db()

if __name__ == '__main__':
    app.run(host='127.0.0.1', port=5000, debug=False)
